import {controller, target} from '@github/catalyst'
import './github/audit-log/audit-log-search-input'
import {IncludeFragmentElement} from '@github/include-fragment-element'

class AsyncQueryStartRequest {
  query_id: string
  results_url: string
  status_url: string
}

@controller
class AsyncAuditLogElement extends HTMLElement {
  targetFetch: IncludeFragmentElement
  @target spinner: HTMLElement
  @target warning: HTMLElement
  @target error: HTMLElement
  @target resultsError: HTMLElement

  closeWarning() {
    this.warning.hidden = true
  }

  showWarning() {
    this.warning.hidden = false
  }

  closeError() {
    this.error.hidden = true
  }

  showError() {
    this.error.hidden = false
  }

  closeResultsError() {
    this.resultsError.hidden = true
  }

  showResults(resultsUrl: string) {
    try {
      this.targetFetch = new IncludeFragmentElement()
      this.targetFetch.setAttribute('src', resultsUrl)
      this.appendChild(this.targetFetch)
    } catch {
      this.showError()

      return
    }
  }

  async connectedCallback() {
    await this.startAndFetchAsyncQuery()
  }

  private async startAndFetchAsyncQuery() {
    const spinner = this.spinner
    const csrfInput = document.querySelector<HTMLInputElement>('.js-data-url-csrf')!
    const jsonDownload = document.querySelector<HTMLElement>('.js-download-button')!

    // Show/hide loading state. Set to `true` to hide menu and show loading state.
    function loading(toggle: boolean) {
      spinner.hidden = !toggle
    }

    const start_url = this.getAttribute('data-url')!
    let response: AsyncQueryStartRequest
    const wants = await fetch(
      new Request(start_url, {
        method: 'POST',
        mode: 'same-origin',
        headers: {
          Accept: 'application/json',
          'Scoped-CSRF-Token': csrfInput.value,
          'X-Requested-With': ',XMLHttpRequest',
        },
      }),
    )

    if (wants.ok) {
      response = await wants.json()
    } else if (wants.status === 429) {
      this.showWarning()
      return
    } else {
      this.showError()
      return
    }

    // Loading results
    loading(true)

    try {
      await fetchPoll(response.status_url, 2000)
    } catch {
      loading(false)
      this.showError()
      return
    }

    loading(false)
    this.showResults(response.results_url)
    jsonDownload.hidden = false
  }
}

function fetchPoll(url: string, pollIntervalMs: number) {
  return new Promise((resolve, reject) => {
    setTimeout(async () => {
      const request = new Request(url)
      request.headers.append('X-Requested-With', 'XMLHttpRequest')
      const response = await fetch(request)
      if (response.status === 200) {
        // Resource is ready.
        resolve(response)
      } else if (response.status === 202) {
        resolve(fetchPoll(url, pollIntervalMs))
      } else {
        // Something unexpected happened.
        reject(response)
      }
    }, pollIntervalMs) // Poll the endpoint every intervalMs
  })
}
